package branching

import (
	"context"
	"database/sql"
	"fmt"
	"strings"

	"github.com/google/uuid"

	"github.com/TrebuchetDynamics/gormes-agent/internal/llm"
	sessionpkg "github.com/TrebuchetDynamics/gormes-agent/internal/persistence/session"
	"github.com/TrebuchetDynamics/gormes-agent/internal/persistence/transcript"
	"github.com/TrebuchetDynamics/gormes-agent/internal/tui"
	"github.com/TrebuchetDynamics/gormes-agent/internal/tui/local/sessionadapters/sessiondb"
	"github.com/TrebuchetDynamics/gormes-agent/internal/tui/local/sessionadapters/switching"
)

type BranchIDFunc func() string

func NewSessionBranchFunc(rootCtx context.Context, metadata sessionpkg.MetadataWriter, resume func(string, []llm.Message) error) tui.SessionBranchFunc {
	return NewSessionBranchFuncWithID(rootCtx, metadata, resume, NewSessionBranchID)
}

func NewSessionBranchFuncWithID(rootCtx context.Context, metadata sessionpkg.MetadataWriter, resume func(string, []llm.Message) error, newID BranchIDFunc) tui.SessionBranchFunc {
	switcher := switching.NewResidentSessionSwitcher(rootCtx, resume)
	return func(ctx context.Context, req tui.BranchRequest) (tui.BranchResult, error) {
		ctx = switcher.Context(ctx)
		if err := switcher.RequireResume(); err != nil {
			return tui.BranchResult{}, err
		}
		if metadata == nil {
			return tui.BranchResult{}, fmt.Errorf("metadata store unavailable")
		}
		childID := strings.TrimSpace(newID())
		if childID == "" {
			return tui.BranchResult{}, fmt.Errorf("child session id unavailable")
		}
		db, err := sessiondb.OpenDirectory()
		if err != nil {
			return tui.BranchResult{}, err
		}
		defer db.Close()

		forked, err := sessionpkg.Fork(ctx, metadata, transcriptTurnCopier{db: db}, sessionpkg.ForkRequest{
			ParentSessionID: req.ParentSessionID,
			ChildSessionID:  childID,
			Title:           req.Title,
		})
		if err != nil {
			return tui.BranchResult{}, err
		}

		if _, err := switcher.SwitchWithTranscriptDB(ctx, db, forked.SessionID, req.History); err != nil {
			return tui.BranchResult{}, err
		}

		return tui.BranchResult{
			SessionID:        forked.SessionID,
			ParentSessionID:  forked.ParentSessionID,
			Title:            forked.Title,
			TranscriptCopied: forked.TranscriptCopied,
		}, nil
	}
}

type transcriptTurnCopier struct {
	db *sql.DB
}

func (c transcriptTurnCopier) CopyTurns(ctx context.Context, parentSessionID, childSessionID string) (int, error) {
	return transcript.ForkTurns(ctx, c.db, parentSessionID, childSessionID)
}

func NewSessionBranchID() string {
	return "branch-" + strings.ReplaceAll(uuid.NewString(), "-", "")
}

package directory

import (
	"context"
	"errors"
	"fmt"
	"strings"

	appsession "github.com/TrebuchetDynamics/gormes-agent/internal/app/session"
	"github.com/TrebuchetDynamics/gormes-agent/internal/config"
	"github.com/TrebuchetDynamics/gormes-agent/internal/llm"
	sessionpkg "github.com/TrebuchetDynamics/gormes-agent/internal/persistence/session"
	"github.com/TrebuchetDynamics/gormes-agent/internal/tui"
	"github.com/TrebuchetDynamics/gormes-agent/internal/tui/local/sessionadapters/sessiondb"
	"github.com/TrebuchetDynamics/gormes-agent/internal/tui/local/sessionadapters/switching"
)

func NewSessionDirectoryFunc(ctx context.Context) tui.SessionDirectoryFunc {
	return func(limit int) ([]tui.SessionDirectoryEntry, error) {
		if limit <= 0 {
			limit = 20
		}
		db, err := sessiondb.OpenDirectory()
		if err != nil {
			if sessiondb.IsMemoryDatabaseNotFound(err) {
				return nil, nil
			}
			return nil, err
		}
		defer db.Close()

		sessions, err := sessionpkg.ListDirectorySessions(ctx, db, sessionpkg.DirectoryFilter{Limit: limit})
		if err != nil {
			return nil, err
		}
		sessions = appsession.ApplySessionMirrorSources(sessions, config.SessionIndexMirrorPath())
		out := make([]tui.SessionDirectoryEntry, 0, len(sessions))
		for _, item := range sessions {
			out = append(out, tui.SessionDirectoryEntry{
				ID:           item.ID,
				Title:        item.Title,
				Preview:      item.Preview,
				Source:       item.Source,
				LastActiveAt: item.LastActiveAt,
				MessageCount: item.MessageCount,
			})
		}
		return out, nil
	}
}

func NewSessionResumeFunc(rootCtx context.Context, resume func(string, []llm.Message) error) tui.SessionResumeFunc {
	switcher := switching.NewResidentSessionSwitcher(rootCtx, resume)
	return func(ctx context.Context, query string) (tui.SessionResumeResult, error) {
		ctx = switcher.Context(ctx)
		query = strings.TrimSpace(query)
		if query == "" {
			return tui.SessionResumeResult{}, fmt.Errorf("session id or prefix required")
		}
		if err := switcher.RequireResume(); err != nil {
			return tui.SessionResumeResult{}, err
		}
		db, err := sessiondb.OpenDirectory()
		if err != nil {
			return tui.SessionResumeResult{}, err
		}
		defer db.Close()

		resolved, err := sessionpkg.ResolveSessionIDPrefix(ctx, db, query)
		if err != nil {
			if errors.Is(err, sessionpkg.ErrSessionNotFound) {
				return tui.SessionResumeResult{}, fmt.Errorf("session %q not found", query)
			}
			if errors.Is(err, sessionpkg.ErrSessionPrefixAmbiguous) {
				return tui.SessionResumeResult{}, fmt.Errorf("session prefix %q is ambiguous: %w", query, err)
			}
			return tui.SessionResumeResult{}, err
		}

		history, err := switcher.SwitchWithTranscriptDB(ctx, db, resolved, nil)
		if err != nil {
			return tui.SessionResumeResult{}, err
		}
		return tui.SessionResumeResult{SessionID: resolved, History: history}, nil
	}
}

package switching

import (
	"context"
	"database/sql"
	"fmt"

	"github.com/TrebuchetDynamics/gormes-agent/internal/llm"
	"github.com/TrebuchetDynamics/gormes-agent/internal/persistence/transcript"
)

type ResumeFunc func(string, []llm.Message) error

type ResidentSessionSwitcher struct {
	rootCtx context.Context
	resume  ResumeFunc
}

func NewResidentSessionSwitcher(rootCtx context.Context, resume ResumeFunc) ResidentSessionSwitcher {
	return ResidentSessionSwitcher{rootCtx: rootCtx, resume: resume}
}

func (s ResidentSessionSwitcher) RequireResume() error {
	if s.resume == nil {
		return fmt.Errorf("kernel resume unavailable")
	}
	return nil
}

func (s ResidentSessionSwitcher) Context(ctx context.Context) context.Context {
	return ContextWithRootFallback(s.rootCtx, ctx)
}

func ContextWithRootFallback(rootCtx, ctx context.Context) context.Context {
	if ctx != nil {
		return ctx
	}
	if rootCtx != nil {
		return rootCtx
	}
	return context.Background()
}

func (s ResidentSessionSwitcher) SwitchWithTranscriptDB(ctx context.Context, db *sql.DB, sessionID string, history []llm.Message) ([]llm.Message, error) {
	if err := s.RequireResume(); err != nil {
		return nil, err
	}
	ctx = s.Context(ctx)
	resolvedHistory := CloneHermesMessages(history)
	if len(resolvedHistory) == 0 {
		messages, err := transcript.LoadMessages(ctx, db, sessionID)
		if err != nil {
			return nil, err
		}
		resolvedHistory = HermesMessagesFromTranscript(messages)
	}
	if err := s.resume(sessionID, resolvedHistory); err != nil {
		return nil, err
	}
	return resolvedHistory, nil
}

func HermesMessagesFromTranscript(messages []transcript.Message) []llm.Message {
	if len(messages) == 0 {
		return nil
	}
	out := make([]llm.Message, 0, len(messages))
	for _, msg := range messages {
		out = append(out, llm.Message{Role: msg.Role, Content: msg.Content})
	}
	return out
}

func CloneHermesMessages(messages []llm.Message) []llm.Message {
	if len(messages) == 0 {
		return nil
	}
	out := make([]llm.Message, len(messages))
	for i, msg := range messages {
		out[i] = msg
		out[i].ContentParts = append([]llm.MessageContentPart(nil), msg.ContentParts...)
	}
	return out
}

